static char sx__str3468[]="";
static char sx__str3469[]="commands:";
static char sx__str3470[]="  init   <name>        Initialize a new project";
static char sx__str3471[]="  build  <config>      Build using a config from sx.mod";
static char sx__str3472[]="  run    <input.sx>    Compile and immediately run a program";
static char sx__str3473[]="  doc    <path>        Generate docs for a given .sx into ./docs-out/";
static char sx__str3474[]="  add    <git-url>     Clone a git dependency into ./lib/ and record it";
static char sx__str3475[]="  remove <dep-name>    Remove a dependency by repository name";
static char sx__str3476[]="  ref                  Generate the language reference in the current directory";
static char sx__str3477[]="  clean                Remove build artifacts";
static char sx__str3478[]="  doctor               Show system and Spectre installation information";
static char sx__str3479[]="";
static char sx__str3480[]="options:";
static char sx__str3481[]="  --ast                Print the AST in a unicode tree and exit";
static char sx__str3482[]="  --syntax-check       Check validity of syntax given some program";
static char sx__str3483[]="  --emit-ssa           Print QBE IR to stdout and exit";
static char sx__str3484[]="  --emit-alt           Print alternative IR to stdout and exit";
static char sx__str3485[]="  --emit-asm           Print assembly to stdout and exit";
static char sx__str3486[]="  --src-target=<os>    Mock target OS for when-blocks in source output";
static char sx__str3487[]="  --translate-c        Translate C input into a single .sx file";
static char sx__str3488[]="  --inc-path=<dir>     Add an include search path for the alt backend";
static char sx__str3489[]="  --show-cmd           Show the command used for linking";
static char sx__str3490[]="  --test               Run the unit tests in the current file";
static char sx__str3491[]="  --release            Build in release mode";
static char sx__str3492[]="  --dll                Build a shared library";
static char sx__str3493[]="  -a, --alt            Compile with fallback backend";
static char sx__str3494[]="  -b, --bootstrap      Display backend output on error";
static char sx__str3495[]="  -c, --compile        Compile only to produce object file, without linking";
static char sx__str3496[]="  -o, --output <file>  Output path for binary or build artifact";
static char sx__str3497[]="  -l, --loud           Show stages of compilation with verbose output";
static char sx__str3498[]="  -v, --version        Show the version of the Spectre compiler";
static char sx__str3499[]="  -h, --help           Print this help message";
